WITH with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM web_events), sessions_web_events AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN island_id >= 8 THEN 'HIGH' ELSE 'LOW' END AS island_id_tier, DATE_TRUNC('YEAR', event_time) AS year_start, PERCENTILE_APPROX(is_new_burst, 0.9) AS is_new_burst_p90, COUNT(*) FILTER (WHERE page = '/cart') AS cart_rows, PERCENTILE_APPROX(duration_sec, 0.95) AS duration_sec_p95 FROM sessions_web_events GROUP BY GROUPING SETS ((CASE WHEN island_id >= 8 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('YEAR', event_time)), (CASE WHEN island_id >= 8 THEN 'HIGH' ELSE 'LOW' END));
